36:     addValidationFromStore(hex: string, isValid: boolean) {
37:         let id = (<Buffer>this.BITBOX.Crypto.sha256(this.BITBOX.Crypto.sha256(Buffer.from(hex, 'hex'))).reverse()).toString('hex');
38:         if(!this.cachedValidations[id])
39:             this.cachedValidations[id] = { hex: hex, validity: isValid, parents: [], details: null, invalidReason: null }
40:         if(!this.cachedRawTransactions[id])
41:             this.cachedRawTransactions[id] = hex;
42:     }
43:     
44:     async waitForParentValidationProcessing(txid: string) {
45:         // TODO: Add some timeout?
46:         let cached: Validation = this.cachedValidations[txid];
47: 
48:         while(true) {
49:             let slpParentCount = cached.parents.length;
50:             let count = 0;
51:             cached.parents.forEach(p => {
52:                 let parent = this.cachedValidations[p.txid];
53:                 if(parent) {
54:                     if(typeof parent.validity === 'boolean')
55:                         count += 1;
56:                 }
57:             });
58:             if(count === slpParentCount && typeof cached.validity === 'boolean')
59:                 break
60:             await sleep(200);
61:         }
62:     }
