64:     async waitForTransactionPreProcessing(txid: string){
65:         // TODO: Add some timeout?
66:         while(true) {
67:             if(this.cachedValidations[txid].hex && this.cachedValidations[txid].details)
68:                 break
69:             await sleep(200);
70:         }
