75:     async getRawTransaction(txid: string) {
76:         if(this.cachedRawTransactions[txid])
77:             return this.cachedRawTransactions[txid];
78:         this.cachedRawTransactions[txid] = (await this.getRawTransactions([txid]))[0]
79:         if(this.cachedRawTransactions[txid])
80:             return this.cachedRawTransactions[txid];
81:         return null;
82:     }
