163:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
164:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
165:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs."
166:                 return this.cachedValidations[txid].validity = false;
167:             }
168:         }
169: 
170:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
171:         for(let i = 0; i < this.cachedValidations[txid].parents.length; i++) {
172:             let valid = await this.isValidSlpTxid(this.cachedValidations[txid].parents[i].txid)
173:             this.cachedValidations[txid].parents.find(p => p.txid === this.cachedValidations[txid].parents[i].txid).valid = valid;
174:             if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.MINT && !valid) {
175:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent."
176:                 return this.cachedValidations[txid].validity = false;
177:             }
178:         }
179: 
180:         // Check valid inputs are greater than token outputs
181:         if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
182:             let validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty) : t }, new BigNumber(0));
183:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
184:             if(tokenOutQty.isGreaterThan(validInputQty)) {
185:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs."
186:                 return this.cachedValidations[txid].validity = false;
187:             }
188:         }
189: 
190:         // Check versionType is not different from any valid parent
191:         if(this.cachedValidations[txid].parents.filter(p => p.valid).length > 0) {
192:             let validVersionType = this.cachedValidations[txid].parents.find(p => p.valid).versionType;
193:             if(this.cachedValidations[txid].details.versionType !== validVersionType) {
194:                 this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid parent."
195:                 return this.cachedValidations[txid].validity = false;
196:             }
197:         } 
198:         // For case with 0 token SEND with no valid parents, must check GENESIS validity / versionType.
199:         else if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
200:             let slpmsg = this.cachedValidations[txid].details
201:             let valid = await this.isValidSlpTxid(slpmsg.tokenIdHex);
202:             if(valid) {
203:                 let genesisTxn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[slpmsg.tokenIdHex].hex)
204:                 let genesisMsg = this.slp.parseSlpOutputScript(genesisTxn.outputs[0]._scriptBuffer)
205:                 if(genesisMsg.versionType !== slpmsg.versionType) {
206:                     this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid GENESIS."
207:                     return this.cachedValidations[txid].validity = false;
208:                 }
209:             } else {
210:                 this.cachedValidations[txid].invalidReason = "SEND has 0 outputs, but has invalid token GENESIS."
211:                 console.log(this.cachedValidations[slpmsg.tokenIdHex].invalidReason)
212:                 return this.cachedValidations[txid].validity = false;
213:             }
214:         }
215: 
216:         return this.cachedValidations[txid].validity = true;
217:     }
218: 
219:     async validateSlpTransactions(txids: string[]): Promise<string[]> {
220:         let res = [];
221:         for (let i = 0; i < txids.length; i++) {
222:             res.push((await this.isValidSlpTxid) ? txids[i] : '')
223:         }
224:         return res.filter((id: string) => id.length > 0);
225:     }
226: }

